#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=28

# ── Helpers for this wizard ────────────────────────────────────────────────
# Gemini Enterprise setup for #49; run it with: bash pilot/workflows/ge-setup.sh
# Everything the pilot owner copies lands in the repo-root .env (gitignored),
# so a re-run offers it back and the #48 wizard can reuse
# CONDITIONS_CALENDAR_ID and TEAM_ALERT_EMAILS. The dated record
# pilot/workflows/setup-<date>.md is rebuilt from setup-template.md after
# every stage. Nothing secret is ever asked for.

shopt -u patsub_replacement 2>/dev/null || true   # bash 5.2+: keep & literal in replacements

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$ROOT"

REPO=m1kulabs/Skyclause
WORKFLOWS_DIR=pilot/workflows
TEMPLATE=$WORKFLOWS_DIR/setup-template.md
REPLAY_FILE=crossing-20261102-1505-01.json
CALLBACK=https://vertexaisearch.cloud.google.com/oauth-redirect
GE_CONSOLE=https://console.cloud.google.com/gemini-enterprise/
DEFAULT_SPF='v=spf1 include:_spf.google.com ~all'
EMAIL_RE='^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'

# Every value the wizard saves; the template's {{KEY}} placeholders use these names.
KEYS=(GE_SETUP_DATE WORKSPACE_DOMAIN PILOT_OWNER_EMAIL TEAM_ALERT_GMAIL TEAM_ALERT_OUTLOOK TEAM_ALERT_EMAILS
  JIRA_SITE JIRA_CLOUD_ID JIRA_PROJECT JIRA_OAUTH_APP_NAME JIRA_USER_MANAGEMENT JIRA_ADMIN_GROUP JIRA_REPLAY_ISSUE_KEY
  CONDITIONS_CALENDAR_ID CONDITIONS_ICS_URL CONDITIONS_LOGGED_OUT CONDITIONS_PRIVATE_WINDOW
  REPLAY_CALENDAR_ID REPLAY_LOGGED_OUT ICS_CHECKED_AT CONDITIONS_CALENDAR_ID_STORED
  DKIM_SELECTOR DKIM_STARTED DNS_CHECKED_AT MAIL_DNS
  CROSSINGS_REPLAY_FOLDER_ID SPIKE_SHEET_ID
  GE_PROJECT_ID GE_LICENCE GE_EDITION GE_OWNER_ROLE GE_APP_NAME GE_APP_ID GE_APP_LOCATION GE_FEATURES
  GE_STORE_DRIVE GE_STORE_DRIVE_ACTIONS GE_STORE_GMAIL GE_STORE_GMAIL_ACTIONS
  GE_STORE_CALENDAR GE_STORE_CALENDAR_ACTIONS GE_STORE_JIRA GE_STORE_JIRA_ACTIONS
  GE_APP_URL ORG_POLICY_EXCEPTION GE_TEAM_INBOX GE_SPIKE_WORKFLOW GE_SPIKE_BUILT_ON
  GE_RUN1 GE_RUN2 GE_RUN3 DEADLINE_CHECK SPEC_EDITS COMMENT_47)
for n in 1 2 3 4 5 6 7 8; do KEYS+=("SPIKE${n}_METHOD" "SPIKE${n}_RUN" "SPIKE${n}_ANSWER"); done
for k in "${KEYS[@]}"; do printf -v "$k" '%s' "$(_existing "$k" || true)"; done
RENDERED_AT=""   # read through ${!k} in render
LAST_COMMENT_URL=""

myt() { TZ=Asia/Kuala_Lumpur date "$@"; }
now_myt() { myt '+%Y-%m-%d %H:%M MYT'; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
show() { sed 's/^/    /' "$1"; }
open_ge_console() { open_url "$GE_CONSOLE?project=$GE_PROJECT_ID"; }

# open_stage "Title" KEY opens a stage. KEY is the last value the stage saves:
# when an earlier run saved it (and it isn't "blocked: ..."), the human can
# skip the stage, and open_stage returns 1.
open_stage() {
  stage "$1"
  local v=${!2}
  if [[ -z "$v" || "$v" == blocked* ]]; then return 0; fi
  note "Done on an earlier run: $2 = $v"
  if confirm "Redo this stage?"; then return 0; fi
  return 1
}

# end_stage rebuilds the record and waits, so the ✓ lines stay readable.
end_stage() { render; pause "Saved to $RECORD. Press Enter for the next stage."; }

# ask_match KEY "Prompt" REGEX "hint" asks until the answer matches, then saves it.
ask_match() {
  while :; do
    ask "$1" "$2"
    if [[ "${!1}" =~ $3 ]]; then break; fi
    warn "That doesn't look right: ${4:-try again}."
  done
  write_env "$1" "${!1}"
}

# ask_or KEY "Prompt" "suggestion": Enter, with nothing saved yet, takes the suggestion.
ask_or() {
  if [[ -z "${!1}" ]]; then note "Enter accepts: $3"; fi
  ask "$1" "$2"
  if [[ -z "${!1}" ]]; then printf -v "$1" '%s' "$3"; fi
  write_env "$1" "${!1}"
}

# ask_id KEY "Prompt" folders|d takes a Drive or Sheets URL, or the bare ID in it.
ask_id() {
  local re="/$3/([A-Za-z0-9_-]+)"
  while :; do
    ask "$1" "$2"
    if [[ "${!1}" =~ $re ]]; then printf -v "$1" '%s' "${BASH_REMATCH[1]}"; fi
    if [[ "${!1}" =~ ^[A-Za-z0-9_-]{20,}$ ]]; then break; fi
    warn "Paste the whole address from the browser's address bar, or just the ID in it."
  done
  write_env "$1" "${!1}"
}

# ask_calendar_id KEY "Calendar name" OTHER_ID... asks for a secondary calendar's ID.
ask_calendar_id() {
  local key=$1 name=$2 other clash
  shift 2
  while :; do
    ask_match "$key" "Calendar ID:" "$EMAIL_RE" "an ID with an @, from Integrate calendar"
    clash=""
    for other in "$PILOT_OWNER_EMAIL" "$@"; do
      if [[ "${!key}" == "$other" ]]; then clash=1; fi
    done
    if [[ -z "$clash" ]]; then break; fi
    warn "That's another calendar; copy the ID of $name."
  done
}

# ask_block NAME "What to paste" saves a multi-line paste to the evidence folder.
ask_block() {
  local file=$EVIDENCE/$1.txt line
  if [[ -s "$file" ]] && ! confirm "$2: saved already. Replace it?"; then return 0; fi
  step "$2"
  note "Paste it below, then type a line with just a dot (.) and press Enter."
  : > "$file"
  while IFS= read -r line; do
    line=${line%$'\r'}
    if [[ "$line" == . ]]; then break; fi
    printf '%s\n' "$line" >> "$file"
  done
  ok "saved $file"
}

# confirm_actions KEY "actions" waits until the human has enabled the actions.
confirm_actions() {
  until confirm "Are these actions enabled: $2?"; do pause "Enable them, then press Enter."; done
  write_env "$1" "$2"
}

# shot NAME "what" saves a screenshot to the evidence folder.
shot() {
  local file=$EVIDENCE/$1.png
  step "Screenshot: $2."
  if command -v screencapture >/dev/null 2>&1 \
    && confirm "Take it now? (Space, then click the browser window; Esc cancels)"; then
    screencapture -i "$file" || true
  else
    say "Save it as $file"
    pause "Press Enter once it's saved."
  fi
  if [[ -s "$file" ]]; then ok "saved $file"; else warn "No screenshot at $file yet."; SKIPPED+=("screenshot $file"); fi
}

# clip FILE copies FILE to the clipboard where a clipboard tool exists.
clip() {
  if command -v pbcopy >/dev/null 2>&1; then pbcopy < "$1"
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe < "$1"
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard < "$1"
  else note "Copy it from $1"; return 0; fi
  ok "copied $(basename "$1") to the clipboard"
}

# run_logged FILE CMD... saves the command line and its output, errors included.
run_logged() {
  local file=$1 rc=0
  shift
  { printf '$'; printf ' %q' "$@"; printf '\n'; "$@" 2>&1 || rc=$?; } > "$file"
  if (( rc )); then printf '(exit status %s)\n' "$rc" >> "$file"; fi
  return "$rc"
}

url_encode_id() { local s=${1//@/%40}; s=${s//#/%23}; printf '%s' "${s//+/%2B}"; }
public_ics_url() { printf 'https://calendar.google.com/calendar/ical/%s/public/basic.ics' "$(url_encode_id "$1")"; }

# render rebuilds the record from the template: {{KEY}} takes the saved value
# ("pending" when there's none) and a {{BLOCK:name}} line takes the evidence
# file name.txt, indented to match.
render() {
  local line k v pad file re='^([[:space:]]*)\{\{BLOCK:([a-z0-9-]+)\}\}$'
  # shellcheck disable=SC2034 # read through ${!k} below
  RENDERED_AT=$(now_myt)
  while IFS= read -r line || [[ -n "$line" ]]; do
    if [[ "$line" =~ $re ]]; then
      pad=${BASH_REMATCH[1]}; file=$EVIDENCE/${BASH_REMATCH[2]}.txt
      if [[ -s "$file" ]]; then
        while IFS= read -r v || [[ -n "$v" ]]; do printf '%s%s\n' "$pad" "$v"; done < "$file"
      else
        printf '%spending\n' "$pad"
      fi
      continue
    fi
    if [[ "$line" == *'{{'* ]]; then
      for k in "${KEYS[@]}" RENDERED_AT; do
        if [[ "$line" != *"{{$k}}"* ]]; then continue; fi
        v=${!k:-pending}
        v=${v//|/\\|}
        line=${line//"{{$k}}"/$v}
      done
    fi
    printf '%s\n' "$line"
  done < "$TEMPLATE" > "$RECORD"
}

# prettify FILE... formats with the repo's prettier so `bun run lint` passes.
prettify() {
  if [[ -x node_modules/.bin/prettier ]]; then
    node_modules/.bin/prettier --write --log-level warn "$@" >/dev/null || warn "prettier failed; run bun run lint:fix"
  else
    SKIPPED+=("format the record: bun install && bun run lint:fix")
  fi
}

# post_comment ISSUE FILE posts FILE on the issue when the human agrees.
post_comment() {
  LAST_COMMENT_URL=""
  prettify "$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
    && confirm "Post $2 as a comment on #$1 now with gh?"; then
    if LAST_COMMENT_URL=$(gh issue comment "$1" -R "$REPO" --body-file "$2"); then
      ok "commented: $LAST_COMMENT_URL"
      return 0
    fi
    warn "gh couldn't post it."
  fi
  open_url "https://github.com/$REPO/issues/$1"
  step "Paste the contents of $2 into a new comment there."
  clip "$2"
  pause "Press Enter once it's posted."
}

# dig_mail saves dig output for SPF, DKIM and DMARC and sets DNS_MISSING.
dig_mail() {
  local kind name want file
  DNS_MISSING=""
  for kind in spf dkim dmarc; do
    case $kind in
      spf) name=$WORKSPACE_DOMAIN; want='v=spf1' ;;
      dkim) name=$DKIM_SELECTOR._domainkey.$WORKSPACE_DOMAIN; want='v=DKIM1' ;;
      dmarc) name=_dmarc.$WORKSPACE_DOMAIN; want='v=DMARC1' ;;
    esac
    file=$EVIDENCE/dig-$kind.txt
    if ! run_logged "$file" dig +noall +answer TXT "$name"; then
      warn "$kind: dig failed; see $file"
      DNS_MISSING+=" $kind"
    elif grep -q "$want" "$file"; then
      ok "$kind: found at $name"
    else
      warn "$kind: no $want record at $name yet"
      DNS_MISSING+=" $kind"
    fi
  done
  if [[ $(grep -c 'v=spf1' "$EVIDENCE/dig-spf.txt" || true) -gt 1 ]]; then
    warn "spf: more than one v=spf1 record; merge them into one, or SPF fails."
  fi
  write_env DNS_CHECKED_AT "$(now_myt)"
}

# ics_status ID prints the HTTP status of the calendar's public feed, fetched
# with no session, or "error: <curl's message>".
ics_status() {
  local out
  if out=$(curl -sS -o /dev/null -w '%{http_code}' "$(public_ics_url "$1")" 2>&1); then
    printf '%s' "$out"
  else
    printf 'error: %s' "${out%000}"
  fi
}

# check_calendars records whether each calendar opens logged out: 200 means
# public, 404 means private, anything else is a failed check.
check_calendars() {
  local s
  if [[ -n "$CONDITIONS_CALENDAR_ID" ]]; then
    s=$(ics_status "$CONDITIONS_CALENDAR_ID")
    if [[ "$s" == 200 ]]; then
      write_env CONDITIONS_LOGGED_OUT "HTTP 200: opens logged out"
    else
      write_env CONDITIONS_LOGGED_OUT "blocked: doesn't open logged out yet ($s)"
      warn "The public calendar doesn't open logged out yet ($s). The admin setting can take up to 24 hours."
    fi
  fi
  if [[ -n "$REPLAY_CALENDAR_ID" ]]; then
    s=$(ics_status "$REPLAY_CALENDAR_ID")
    case $s in
      404) write_env REPLAY_LOGGED_OUT "HTTP 404: private" ;;
      200) write_env REPLAY_LOGGED_OUT "blocked: HTTP 200, public, which it must not be"
           warn "The replay calendar is public. Untick Make available to public in its settings." ;;
      *) write_env REPLAY_LOGGED_OUT "blocked: couldn't check ($s)"
         warn "Couldn't check the replay calendar: $s" ;;
    esac
  fi
  write_env ICS_CHECKED_AT "$(now_myt)"
}

# trial_check stops on the #7 licence question when the console asked to pay.
trial_check() {
  if confirm "Did any screen in this stage offer a free trial, or ask for credits or payment?"; then licence_stop; fi
}

licence_stop() {
  local body7=$EVIDENCE/comment-7.md body47=$EVIDENCE/comment-47-licence.md
  write_env GE_LICENCE "blocked: on $(now_myt) the console offered a free trial or asked for credits, so the licence hasn't reached \`${GE_PROJECT_ID:-the project}\` (#7)"
  cat > "$body7" <<EOF
Licence check for #49, $(now_myt): the Gemini Enterprise console in project \`${GE_PROJECT_ID:-unknown}\` offered a free trial or asked for credits, so the sponsored licence hasn't reached that project. Nothing was started or bought.

#49's licence-free steps (the Jira site and OAuth app, the calendars, mail DNS, the spike inputs) go ahead; the app, data stores and spikes wait for the licence. Which project and location were the licences distributed to?
EOF
  render
  prettify "$RECORD"
  _clear
  printf '\n'
  warn "Stop: the licence hasn't reached this project."
  say "Don't start the trial and don't buy credits. Comment on #7 instead:"
  show "$body7"
  post_comment 7 "$body7"
  cat > "$body47" <<EOF
#49, $(now_myt): the Gemini Enterprise licence hasn't reached \`${GE_PROJECT_ID:-the project}\` (#7${LAST_COMMENT_URL:+, $LAST_COMMENT_URL}), so the app and its Drive, Gmail, Calendar and Jira actions can't work by 12:00 MYT on 7 November until it does.
EOF
  say "#49 also asks for a comment on #47 if the app and its actions won't work by 12:00 MYT on 7 November:"
  show "$body47"
  post_comment 47 "$body47"
  write_env DEADLINE_CHECK "blocked: licence not in the project at $(now_myt)${LAST_COMMENT_URL:+ (commented on #47: $LAST_COMMENT_URL)}"
  render
  prettify "$RECORD"
  say ""
  say "The licence-free steps are saved in $RECORD."
  say "Once the licence reaches the project, re-run: bash $WORKFLOWS_DIR/ge-setup.sh"
  say "Finished stages are skipped with Enter."
  exit 0
}

# new_store "Source" opens the console at a new data store for the app.
new_store() {
  open_ge_console
  step "$GE_APP_NAME → Connected data stores → New data store → Source: search $1 → Select."
  note "Or Data stores → Create data store, then connect it under the app's Connected data stores."
  note "If it offers a connector mode, choose Federated search, never Data ingestion: an index is a cached copy."
}

# run_id_help says where a workflow run's ID is.
run_id_help() {
  step "Agents → Runs (or the workflow's Runs tab) → open the run. Copy its ID from the run details; if none shows, copy the run page's address."
}

# spike N "run IDs" "suggested method" "what the answer states" records one spike row.
spike() {
  write_env "SPIKE$1_RUN" "$2"
  ask_or "SPIKE$1_METHOD" "Spike $1 method:" "$3"
  ask_match "SPIKE$1_ANSWER" "Spike $1 answer ($4):" '.+'
}

