  say "Google's Jira connector needs Atlassian's centralised user management."
  step "Open the organisation's Users page. Centralised: Users sits under Directory and has no Site filter. Original: it has a Site filter."
  if confirm "Does the organisation use centralised user management?"; then
    write_env JIRA_USER_MANAGEMENT "centralised, checked $(now_myt)"
  else
    write_env JIRA_USER_MANAGEMENT "blocked: original user management; migrate to centralised first"
    warn "Migrate to centralised user management before the Jira data store stage."
  fi
  step "Manage users → Groups → Create group → a name."
  step "On the group: Add product → Jira: User access admin; Jira administration: Product admin → Grant Access."
  step "Add group members → the pilot owner's Atlassian account, which signs in from the Google console."
  ask_match JIRA_ADMIN_GROUP "Group name:" '.+'
  end_stage
fi

if open_stage "Calendar: Skyclause conditions (pilot)" CONDITIONS_PRIVATE_WINDOW; then
  say "As the pilot owner, create the public calendar."
  open_url "https://calendar.google.com/calendar/r/settings/createcalendar"
  step "Name: Skyclause conditions (pilot) → Create calendar."
  step "Settings for my calendars → Skyclause conditions (pilot) → Access permissions for events."
  step "Tick Make available to public, and pick See all event details."
  note "Missing, or stuck on free/busy? A Workspace admin sets Admin console → Apps → Google Workspace → Calendar → General settings → External sharing options for secondary calendars → Share all information, but outsiders cannot change calendars. It can take up to 24 hours."
  step "Integrate calendar → copy the Calendar ID."
  ask_calendar_id CONDITIONS_CALENDAR_ID "Skyclause conditions (pilot)"
  write_env CONDITIONS_ICS_URL "$(public_ics_url "$CONDITIONS_CALENDAR_ID")"
  check_calendars
  say "Now open this in a private (incognito) window, signed out:"
  say "https://calendar.google.com/calendar/embed?src=$(url_encode_id "$CONDITIONS_CALENDAR_ID")"
  if confirm "Does it show the calendar without signing in?"; then
    write_env CONDITIONS_PRIVATE_WINDOW "it opened without signing in, $(now_myt)"
