fi

if open_stage "Calendar: Skyclause replay (team)" REPLAY_LOGGED_OUT; then
  say "Create the private replay calendar."
  open_url "https://calendar.google.com/calendar/r/settings/createcalendar"
  step "Name: Skyclause replay (team) → Create calendar."
  step "Settings for my calendars → Skyclause replay (team): leave Make available to public unticked."
  step "Share with specific people or groups → Add people and groups → add each teammate."
  step "Integrate calendar → copy the Calendar ID."
  ask_calendar_id REPLAY_CALENDAR_ID "Skyclause replay (team)" "$CONDITIONS_CALENDAR_ID"
  check_calendars
  end_stage
fi

if open_stage "Store CONDITIONS_CALENDAR_ID" CONDITIONS_CALENDAR_ID_STORED; then
  say "CONDITIONS_CALENDAR_ID = $CONDITIONS_CALENDAR_ID"
  note "It's saved in $ENV_FILE too."
  if confirm "Does the skyclause-pilot Apps Script project exist yet?"; then
    open_url "https://script.google.com/home"
    step "skyclause-pilot → Project Settings → Script Properties → Edit script properties."
    step "Add script property: CONDITIONS_CALENDAR_ID = the ID above → Save script properties."
    pause "Press Enter once it's saved."
    write_env CONDITIONS_CALENDAR_ID_STORED "the Script Properties of \`skyclause-pilot\`"
  else
    write_env CONDITIONS_CALENDAR_ID_STORED "the owner's repo-root \`.env\`, for the #48 wizard to put in Script Properties"
  fi
  end_stage
fi

if open_stage "Mail: DKIM key" DKIM_SELECTOR; then
  say "Generate the DKIM key in the Admin console, signed in as a super admin."
  open_url "https://admin.google.com/ac/apps/gmail/authenticateemail"
  step "Menu → Apps → Google Workspace → Gmail → Authenticate email (the link above opens it)."
  step "Selected domain: $WORKSPACE_DOMAIN → Generate New Record."
  step "Key length 2048 (1024 only if your DNS host can't take 2048 bits). Keep the prefix selector. Generate."
  step "Send the DNS host name and TXT record value it shows to the domain admin for the next stage."
  warn "Don't click Start authentication until the next stage finds the record."
  note "No key offered? Google says the key can take 24–72 hours after Gmail is turned on."
  ask_or DKIM_SELECTOR "Prefix selector it shows:" "google"
  end_stage
fi

if open_stage "Mail: SPF, DKIM and DMARC records" MAIL_DNS; then
  say "Checking $WORKSPACE_DOMAIN's records with dig:"
  while :; do
    dig_mail
    if [[ -z "$DNS_MISSING" ]]; then break; fi
    printf '\n'
    say "The domain admin adds these TXT records at the DNS host:"
    if [[ "$DNS_MISSING" == *spf* ]]; then
      step "SPF at $WORKSPACE_DOMAIN (host @): $DEFAULT_SPF"
      note "That's Google's value for a domain that sends only through Workspace. If a v=spf1 record exists, add include:_spf.google.com to it; a domain has one SPF record."
    fi
    if [[ "$DNS_MISSING" == *dkim* ]]; then
      step "DKIM at $DKIM_SELECTOR._domainkey.$WORKSPACE_DOMAIN: the value from Authenticate email."
    fi
    if [[ "$DNS_MISSING" == *dmarc* ]]; then
      step "DMARC at _dmarc.$WORKSPACE_DOMAIN: a record starting v=DMARC1; p=none"
      note "Only v and p are required, and Google recommends starting at p=none. Add rua=mailto:<an address you read> for reports if you like."
      note "Google advises waiting 48 hours after SPF and DKIM before DMARC; the 7 November deadline doesn't allow that."
    fi
    if ! confirm "Re-check now? (No leaves this stage for a re-run.)"; then break; fi
  done
  if [[ "$DNS_MISSING" != *dkim* && -z "$DKIM_STARTED" ]]; then
    open_url "https://admin.google.com/ac/apps/gmail/authenticateemail"
    step "Selected domain: $WORKSPACE_DOMAIN → Start authentication."
    if confirm "Does the status now say it's authenticating email?"; then
      write_env DKIM_STARTED "started $(now_myt)"
    else
      warn "Not started; Google says DKIM can take up to 48 hours after the record is added. Re-run later."
    fi
  fi
  if [[ -z "$DNS_MISSING" && -n "$DKIM_STARTED" ]]; then
    write_env MAIL_DNS "SPF, DKIM and DMARC found and DKIM signing started, $(now_myt)"
  else
    SKIPPED+=("mail authentication: missing${DNS_MISSING:- nothing}, DKIM signing ${DKIM_STARTED:-not started} (re-run this wizard)")
  fi
  end_stage
fi

if open_stage "Spike inputs: replay folder, spike spreadsheet and replay file" SPIKE_SHEET_ID; then
  say "As the pilot owner (Drive only searches files owned in the owner's domain):"
  open_url "https://drive.google.com/drive/my-drive"
  step "Open Skyclause pilot → crossings-replay → sky."
  note "If #48's setup() hasn't run yet, create those three folders in My Drive with exactly those names; setup() finds them by name."
  ask_id CROSSINGS_REPLAY_FOLDER_ID "The sky folder's URL or ID:" folders
  open_url "https://sheets.new"
  step "Name the new spreadsheet; it's the spike spreadsheet. Never use the pilot workbook or its ledger."
  ask_id SPIKE_SHEET_ID "Spike spreadsheet's URL or ID:" d
  ok "replay file ready: $EVIDENCE/$REPLAY_FILE (the spec's Crossing file example, replay: true)"
  note "Don't upload it yet: it starts the spike run once the workflow exists."
  end_stage
fi

# ── Gemini Enterprise: needs the licence ───────────────────────────────────
if open_stage "Gemini Enterprise: licence check" GE_LICENCE; then
  say "A licence works only in the project and location it was distributed to (#7)."
  ask_match GE_PROJECT_ID "Google Cloud project ID the licence reached:" '^[a-z][a-z0-9-]{4,28}[a-z0-9]$' "a lower-case project ID"
  open_ge_console
  say "Look at the Gemini Enterprise page before clicking anything."
  if confirm "Does it offer 'Start a free trial', or ask you to buy credits?"; then licence_stop; fi
  step "Open the subscription details and read the edition (for example Standard or Plus)."
  ask_match GE_EDITION "Edition:" '.+'
  write_env GE_LICENCE "reached \`$GE_PROJECT_ID\`, checked $(now_myt)"
  end_stage
fi

if open_stage "Gemini Enterprise: owner role" GE_OWNER_ROLE; then
  say "$PILOT_OWNER_EMAIL needs Discovery Engine Editor (roles/discoveryengine.editor)."
  open_url "https://console.cloud.google.com/iam-admin/iam?project=$GE_PROJECT_ID"
  step "Find $PILOT_OWNER_EMAIL → Edit → Add another role → Discovery Engine Editor → Save."
  note "A project admin does this if you can't."
  pause "Press Enter once it's granted."
  while :; do
    if command -v gcloud >/dev/null 2>&1; then
      run_logged "$EVIDENCE/owner-roles.txt" gcloud projects get-iam-policy "$GE_PROJECT_ID" \
        --flatten='bindings[].members' --filter="bindings.members:user:$PILOT_OWNER_EMAIL" \
        --format='value(bindings.role)' || true
      show "$EVIDENCE/owner-roles.txt"
    else
      printf 'gcloud not installed; checked on the IAM page only\n' > "$EVIDENCE/owner-roles.txt"
    fi
    if grep -q 'roles/discoveryengine.editor' "$EVIDENCE/owner-roles.txt"; then
      write_env GE_OWNER_ROLE "\`roles/discoveryengine.editor\`, seen by gcloud $(now_myt)"
      break
    fi
    if confirm "Does the IAM page show Discovery Engine Editor for $PILOT_OWNER_EMAIL?"; then
      write_env GE_OWNER_ROLE "\`roles/discoveryengine.editor\`, seen on the IAM page $(now_myt)"
      break
    fi
    pause "Grant it, then press Enter to check again."
  done
  end_stage
fi

