  say "Reviewers can also start runs by emailing the team inbox."
  ask_match GE_TEAM_INBOX "Team inbox address the Gmail trigger watches:" "$EMAIL_RE" "an email address"
  ask_match ORG_POLICY_EXCEPTION "From that policy, is an exception needed for reviewers outside $WORKSPACE_DOMAIN? (yes, no or unknown, and why):" '.+'
  end_stage
fi

# ── Spikes ─────────────────────────────────────────────────────────────────
if open_stage "Spike workflow: build it" GE_SPIKE_WORKFLOW; then
  write_node_files
  say "One workflow answers all eight spikes and stays as the crossing replay copy."
  warn "Standard gives one agent creation or draft per seat a day, pooled. Build this one by hand, edit it in place, and don't generate it from a prompt or start a second."
  open_url "$GE_APP_URL"
  step "Agents → Create agent → Start manually → App event → Google Drive (Connect if asked)."
  step "Pick the event for a new file, filtered to the folder $CROSSINGS_REPLAY_FOLDER_ID (Skyclause pilot/crossings-replay/sky)."
  note "If the trigger offers no folder filter, write that down for spike 3."
  step "Add step → Gemini agent node, named Draft. Model: Gemini 3.1 Pro, which Workflow Builder's known issues recommend."
  step "  Connected apps: Google Drive, with Add Or Update Data off. Instructions: paste them now."
  clip "$EVIDENCE/node-draft.txt"
  pause "Press Enter once the Draft node is set."
  step "Add step → Human in the loop → Request info, with this message and two Short answer questions:"
  show "$EVIDENCE/request-info.txt"
  clip "$EVIDENCE/request-info.txt"
  pause "Press Enter once Request info is set."
  step "Add step → Human in the loop → Approval: show the reviewer the Draft output and the Request info answers."
  step "Add step → Gemini agent node, named Write. Connected apps: Jira Cloud, Google Calendar, Gmail and"
  step "  Google Drive, each with Add Or Update Data on (Connect any that ask). Instructions: paste them now."
  clip "$EVIDENCE/node-write.txt"
  pause "Press Enter once the Write node is set."
  step "Save, then Turn on."
  write_env GE_SPIKE_BUILT_ON "$(myt +%F)"
  ask_match GE_SPIKE_WORKFLOW "Workflow name:" '.+'
  end_stage
fi

if open_stage "Spike run 1: upload the replay file and edit the call" GE_RUN1; then
  open_url "https://drive.google.com/drive/folders/$CROSSINGS_REPLAY_FOLDER_ID"
  if [[ "$(uname)" == Darwin ]]; then open -R "$EVIDENCE/$REPLAY_FILE" || true; fi
  step "Drag $EVIDENCE/$REPLAY_FILE into the sky folder."
  note "The trigger polls, so the run can take 5–10 minutes to start."
  open_url "$GE_APP_URL"
  step "Agents → $GE_SPIKE_WORKFLOW → Runs. Wait for a run showing Needs Review."
  say "The teammate reviews, in the owner's signed-in session (or their own, if they hold a seat and the workflow is shared with them):"
  step "Request info: Calls to reject: none. Edits: change call 1's wording, keeping 'Replay (2 Nov 2026):' at the start of its subject."
  step "Approval: approve."
  step "For spike 2, count every further review the run asks for before it shows Completed."
  run_id_help
  ask_match GE_RUN1 "Run 1's ID:" '.+'
  end_stage
fi

if open_stage "12:00 check: the app's Drive, Gmail, Calendar and Jira actions" DEADLINE_CHECK; then
  if (( $(myt +%Y%m%d%H%M) > 202611071200 )); then late="after"; else late="before"; fi
  say "By 12:00 MYT on 7 November these must work, or comment on #47. It's $(now_myt), $late the deadline."
  failed=""
  if ! confirm "Drive: did the Draft node read the file, and did the spike spreadsheet get a row?"; then failed+="Drive, "; fi
  if ! confirm "Gmail: did both team inboxes get the Replay (2 Nov 2026): message?"; then failed+="Gmail, "; fi
  if ! confirm "Calendar: is there an event on Skyclause replay (team)?"; then failed+="Calendar, "; fi
  if confirm "Jira: did the connector create a SKY issue labelled replay?"; then
    open_url "$JIRA_SITE/issues/?jql=project%20%3D%20SKY%20AND%20labels%20%3D%20replay"
    ask_match JIRA_REPLAY_ISSUE_KEY "Its key:" '^SKY-[0-9]+$' "SKY-<number>"
  else
    failed+="Jira, "
  fi
  if [[ -z "$failed" ]]; then
    write_env DEADLINE_CHECK "Drive, Gmail, Calendar and Jira actions all worked in run $GE_RUN1, $(now_myt)"
  else
    failed=${failed%, }
    warn "Not working: $failed."
    cat > "$EVIDENCE/comment-47-deadline.md" <<EOF
#49 check, $(now_myt): in app \`$GE_APP_ID\`, these actions didn't work in spike run $GE_RUN1: $failed. The deadline is 12:00 MYT on 7 November.
EOF
    post_comment 47 "$EVIDENCE/comment-47-deadline.md"
    write_env DEADLINE_CHECK "blocked: not working at $(now_myt): $failed${LAST_COMMENT_URL:+ (commented on #47: $LAST_COMMENT_URL)}"
  fi
  end_stage
fi

if open_stage "Spike run 2: reject the call; spikes 1 and 2" SPIKE2_ANSWER; then
  say "The replay file holds one change, so it drafts one call: run 1 edited it, run 2 rejects it."
  open_url "https://drive.google.com/drive/folders/$CROSSINGS_REPLAY_FOLDER_ID"
  step "Drag $REPLAY_FILE into the sky folder again; Drive keeps both copies and the trigger sees a new file."
  step "Teammate, at Request info: Calls to reject: 1. Edits: none. Then approve."
  step "Check: no new Jira issue, calendar event or email; only a 'rejected' row in the spike spreadsheet."
  run_id_help
  ask_match GE_RUN2 "Run 2's ID:" '.+'
  printf '\n'
  say "Spike 1: with Request info then Approval, can one call be edited and one rejected (CAL-6)?"
  spike 1 "$GE_RUN1, $GE_RUN2" \
    "Run 1 edited the call at Request info and run 2 rejected it; the replay file drafts one call per run" \
    "did the edit and the rejection each reach the writes?"
  say "Spike 2: do four writes after one Approval need one review or four?"
  spike 2 "$GE_RUN1" \
    "Counted the reviews run 1 asked for after its one Approval, across the Jira, Calendar, Gmail and Sheets writes" \
    "how many reviews"
  end_stage
fi

if open_stage "Spikes 3 and 4: trigger and file content" SPIKE4_ANSWER; then
  open_url "$GE_APP_URL"
  step "Open run 1 ($GE_RUN1): read the trigger step's output and the Draft node's TRIGGER and CONTENT lines."
  say "Spike 3: does the Drive trigger pass file content, or only the name and ID?"
  spike 3 "$GE_RUN1" "Read the trigger step's output in run 1 and the Draft node's TRIGGER line" "content, or name and ID"
  say "Spike 4: does the Drive connector read .json content, and if not, a Google Doc?"
  if confirm "Did the Draft node read the .json file's content?"; then
    spike 4 "$GE_RUN1" "The Draft node's CONTENT line in run 1, on the .json file" "reads .json: yes or no"
  else
    say "Try a Google Doc with the same text:"
    clip "$EVIDENCE/$REPLAY_FILE"
    open_url "https://drive.google.com/drive/folders/$CROSSINGS_REPLAY_FOLDER_ID"
    step "New → Google Docs → Blank document, named crossing-20261102-1505-01, with the replay file's text pasted in."
    step "That starts run 3. Teammate, at Request info: Calls to reject: 1, so it writes only the spike row. Then approve."
    run_id_help
    ask_match GE_RUN3 "Run 3's ID:" '.+'
    spike 4 "$GE_RUN1, $GE_RUN3" \
      "The Draft node's CONTENT line in run 1 (.json) and run 3 (a Google Doc with the same text)" \
      "reads .json: no; reads the Google Doc: yes or no"
  fi
  end_stage
fi

if open_stage "Spikes 5 and 6: replay calendar and current time" SPIKE6_ANSWER; then
  open_url "https://calendar.google.com/calendar/r/week/2026/11/2"
  step "Week of 2 November 2026: find run 1's event. Is it on Skyclause replay (team), and nowhere else?"
  say "Re-checking that the public calendar opens logged out and the replay calendar doesn't:"
  check_calendars
  say "Spike 5: can Calendar Create event target a non-primary calendar?"
  spike 5 "$GE_RUN1" \
    "The Write node's Create event in run 1, given the replay calendar's ID; checked which calendar the event landed on" \
    "which calendar it landed on"
  open_url "$GE_APP_URL"
  step "Open run 1 ($GE_RUN1): read the Draft node's TIME line and the trace around it."
  say "Spike 6: does GE expose the current time to a node, for drafted_at?"
  warn "A model's guess doesn't count: name the platform field in the trace the time came from, or answer no."
  spike 6 "$GE_RUN1" \
    "The Draft node's TIME line in run 1, checked against the run's Started time and the trace field it names" \
    "yes, from <field>, or no"
  end_stage
fi

if open_stage "Spike 7: plain-text part and DMARC" SPIKE7_ANSWER; then
  say "The teammates who own the two addresses open run 1's message."
  step "Gmail ($TEAM_ALERT_GMAIL): open the message → More → Show original."
  step "  Note whether the source has a Content-Type: text/plain part, and whether SPF, DKIM and DMARC say PASS."
  ask_block headers-gmail "Gmail's Authentication-Results header (only those lines)"
  step "Outlook ($TEAM_ALERT_OUTLOOK): open the message → More actions → View → View message source."
  ask_block headers-outlook "Outlook's Authentication-Results header (only those lines)"
  for f in headers-gmail headers-outlook; do
    if grep -qi 'dmarc=pass' "$EVIDENCE/$f.txt"; then
      ok "$f: dmarc=pass"
    else
      warn "$f: no dmarc=pass"
      SKIPPED+=("spike 7: $f has no dmarc=pass; fix mail DNS and resend")
    fi
  done
  say "Refreshing the dig output:"
  dig_mail
  spike 7 "$GE_RUN1" "Show original in Gmail and View message source in Outlook, on run 1's message" \
    "text/plain part: yes or no; DMARC in each"
  end_stage
fi

if open_stage "Spike 8: daily agent creations" SPIKE8_ANSWER; then
  say "How many agent creations does the pool give per day, and does a workflow copy count?"
  note "Workflow Builder's limits: Standard gives 1 per seat a day and Plus 10, pooled; the pool resets at 16:00 MYT. This edition: $GE_EDITION."
  open_ge_console
  step "Read the seat count on the subscription details."
  step "Then, in the web app, Make a copy of $GE_SPIKE_WORKFLOW and note whether it's refused for quota. Delete the copy afterwards."
  ask_or SPIKE8_RUN "Run ID, if the test made a run:" "none: the copy test makes no run"
  ask_or SPIKE8_METHOD "Spike 8 method:" "Seats on the subscription details times the edition's daily allowance; one Make a copy of the spike workflow"
  ask_match SPIKE8_ANSWER "Spike 8 answer (creations per day for the pool; does a copy count?):" '.+'
  end_stage
fi

if open_stage "Comment on #47" COMMENT_47; then
  say "If an answer breaks a spec decision, propose the edit here; the spec isn't changed in #49."
  ask_or SPEC_EDITS "Proposed spec edits:" "none"
  render
  body=$EVIDENCE/comment-47.md
  {
    printf '#49 spike answers, %s. Setup record: [%s](https://github.com/%s/blob/main/%s), once its PR merges.\n\n' \
      "$(now_myt)" "\`$RECORD\`" "$REPO" "$RECORD"
    awk '/^## Spikes$/ { on = 1; next } on && /^\|/ { print; seen = 1; next } seen { exit }' "$RECORD"
    printf '\n- **Agent creations per day for the pool (spike 8):** %s\n' "$SPIKE8_ANSWER"
    printf -- '- **Spike 1:** the replay file holds one change, so edit and reject were each tested on its one call, in separate runs. Both inside one review needs a crossing file with two or more changes.\n'
    printf -- '- **Proposed spec edits:** %s\n' "$SPEC_EDITS"
  } > "$body"
  show "$body"
  post_comment 47 "$body"
  if [[ -n "$LAST_COMMENT_URL" ]]; then
    write_env COMMENT_47 "$LAST_COMMENT_URL"
  else
    ask_match COMMENT_47 "The comment's URL:" '^https://github\.com/.+' "the comment's link"
  fi
  end_stage
fi

render
prettify "$RECORD" "$EVIDENCE"
finish
say "Setup record: $RECORD (evidence in $EVIDENCE/)"
say "Commit both on a branch and open a PR that says Part of #49:"
note "  git switch -c docs/ge-setup-$GE_SETUP_DATE"
note "  git add $RECORD $EVIDENCE && git commit -m 'docs: record gemini enterprise setup'"
note "  git push -u origin HEAD && gh pr create --title 'docs: record gemini enterprise setup' --body 'Part of #49'"
printf '\n'
}

run_wizard "$@"; exit
